#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Duplikátum-szűrő: hasonlóság-alapú deduplikáció érkezéskor,
mielőtt az üzenet broadcastolódik.

Ez a modul egy önálló, külső függőség nélküli implementáció,
amely:
  - Karakter n-gram vektorizációt végez az üzenetekon
  - Koszinusz hasonlóságot számít az új üzenet és a közelmúltban
    látott üzenetek között
  - Egy csúszó ablakban (ring buffer) tartja a legutóbbi üzeneteket
  - Konfigurálható hasonlósági küszöb és ablakméret
  - Opcionálisan perzisztens gyorsítótár (JSON fájl) támogatás

Használat:
    python dedup_filter.py            # önálló demo / teszt
    python dedup_filter.py --threshold 0.85 --window 200

Importálható más modulokból:
    from dedup_filter import DuplicateFilter
"""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import re
import sys
import time
from collections import deque
from dataclasses import dataclass, field, asdict
from typing import Deque, Dict, List, Optional, Tuple


# ---------------------------------------------------------------------------
# Segédfüggvények: szövegtisztítás és n-gram vektorizáció
# ---------------------------------------------------------------------------

def _normalize(text: str) -> str:
    """Szöveg normalizálása: kisbetűsítés, felesleges whitespace eltávolítása."""
    text = text.lower().strip()
    text = re.sub(r"\s+", " ", text)
    return text


def _char_ngrams(text: str, n: int = 3) -> List[str]:
    """Karakter n-gramok generálása egy normalizált szövegből."""
    text = _normalize(text)
    if len(text) < n:
        return [text] if text else []
    return [text[i : i + n] for i in range(len(text) - n + 1)]


def _word_tokens(text: str) -> List[str]:
    """Szótokenizáció egyszerű regex-szel."""
    return re.findall(r"\w+", _normalize(text))


def _vectorize(text: str, ngram_size: int = 3) -> Dict[str, int]:
    """
    Bag-of-n-grams vektor (term frequencies).
    Visszaad egy dict-et: {ngram: count}.
    """
    ngrams = _char_ngrams(text, ngram_size)
    vec: Dict[str, int] = {}
    for ng in ngrams:
        vec[ng] = vec.get(ng, 0) + 1
    # Szótokensúlyok hozzáadása, hogy a szó-szintű hasonlóság is számítson
    for w in _word_tokens(text):
        key = f"W:{w}"
        vec[key] = vec.get(key, 0) + 2  # a szavak nagyobb súllyal
    return vec


def _cosine_similarity(vec_a: Dict[str, int], vec_b: Dict[str, int]) -> float:
    """Koszinusz hasonlóság két sparse vektor között."""
    if not vec_a or not vec_b:
        return 0.0
    # Kisebb vektor iterálása a gyorsaság érdekében
    if len(vec_a) > len(vec_b):
        vec_a, vec_b = vec_b, vec_a
    dot = 0
    for key, val in vec_a.items():
        if key in vec_b:
            dot += val * vec_b[key]
    norm_a = math.sqrt(sum(v * v for v in vec_a.values()))
    norm_b = math.sqrt(sum(v * v for v in vec_b.values()))
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return dot / (norm_a * norm_b)


def _exact_hash(text: str) -> str:
    """Gyors exact-match hash a teljes szövegre."""
    return hashlib.sha256(_normalize(text).encode("utf-8")).hexdigest()


# ---------------------------------------------------------------------------
# Adatstruktúrák
# ---------------------------------------------------------------------------

@dataclass
class SeenEntry:
    """Egy már látott üzenet metaadatai."""
    text: str
    text_hash: str
    vector: Dict[str, int]
    timestamp: float
    sender: Optional[str] = None
    similarity_hits: int = 0


@dataclass
class DedupResult:
    """A szűrő döntésének eredménye."""
    is_duplicate: bool
    similarity: float
    matched_entry: Optional[SeenEntry] = None
    reason: str = ""


# ---------------------------------------------------------------------------
# Fő osztály: DuplicateFilter
# ---------------------------------------------------------------------------

class DuplicateFilter:
    """
    Hasonlóság-alapú duplikátum-szűrő.

    Paraméterek:
        threshold    – 0..1 közötti küszöbérték; e feletti hasonlóság
                       esetén az üzenet duplikátumnak minősül.
        window_size  – Hány legutóbbi üzenetet tartunk a memóriában.
        ngram_size   – Karakter n-gram méret (alapértelmezett 3).
        min_length   – Minimális szövehossz, ami alatt nem szűrünk
                       (rövid üzenetek túl zajosak).
        cache_path   – Opcionális JSON fájl a perzisztens gyorsítótárhoz.
    """

    def __init__(
        self,
        threshold: float = 0.82,
        window_size: int = 150,
        ngram_size: int = 3,
        min_length: int = 15,
        cache_path: Optional[str] = None,
    ) -> None:
        if not 0.0 <= threshold <= 1.0:
            raise ValueError("threshold must be between 0.0 and 1.0")
        if window_size < 1:
            raise ValueError("window_size must be >= 1")

        self.threshold = threshold
        self.window_size = window_size
        self.ngram_size = ngram_size
        self.min_length = min_length
        self.cache_path = cache_path

        self._buffer: Deque[SeenEntry] = deque(maxlen=window_size)
        self._exact_hashes: Dict[str, float] = {}  # hash -> timestamp

        if cache_path and os.path.exists(cache_path):
            self._load_cache()

    # -- Publikus API -------------------------------------------------------

    def check(self, text: str, sender: Optional[str] = None) -> DedupResult:
        """
        Ellenőrzi, hogy a megadott szöveg duplikátum-e.
        Nem adja hozzá a pufferhez – csak döntést hoz.
        """
        normalized = _normalize(text)

        # 1) Rövid szövegek: csak exact match
        if len(normalized) < self.min_length:
            h = _exact_hash(text)
            if h in self._exact_hashes:
                return DedupResult(
                    is_duplicate=True,
                    similarity=1.0,
                    reason="exact_match_short",
                )
            return DedupResult(is_duplicate=False, similarity=0.0, reason="short_unique")

        # 2) Exact hash ellenőrzés
        h = _exact_hash(text)
        if h in self._exact_hashes:
            return DedupResult(
                is_duplicate=True,
                similarity=1.0,
                reason="exact_match",
            )

        # 3) Hasonlóság-alapú ellenőrzés
        incoming_vec = _vectorize(text, self.ngram_size)
        best_sim = 0.0
        best_entry: Optional[SeenEntry] = None

        for entry in self._buffer:
            sim = _cosine_similarity(incoming_vec, entry.vector)
            if sim > best_sim:
                best_sim = sim
                best_entry = entry
                if sim >= 1.0:
                    break

        if best_sim >= self.threshold and best_entry is not None:
            return DedupResult(
                is_duplicate=True,
                similarity=best_sim,
                matched_entry=best_entry,
                reason="similarity_threshold",
            )

        return DedupResult(
            is_duplicate=False,
            similarity=best_sim,
            matched_entry=best_entry if best_sim > 0 else None,
            reason="unique",
        )

    def admit(self, text: str, sender: Optional[str] = None) -> DedupResult:
        """
        Ellenőrzi és ha nem duplikátum, hozzáadja a pufferhez.
        Ez a fő belépési pont a broadcast előtt.
        Visszaadja a döntést.
        """
        result = self.check(text, sender)
        if not result.is_duplicate:
            self._add(text, sender)
        else:
            # Ha duplikátum, növeljük a találati számlálót
            if result.matched_entry is not None:
                result.matched_entry.similarity_hits += 1
        return result

    def should_broadcast(self, text: str, sender: Optional[str] = None) -> bool:
        """
        Egyszerű boolean wrapper: True ha broadcastolni kell,
        False ha duplikátum.
        """
        return not self.admit(text, sender).is_duplicate

    # -- Belső metódusok ----------------------------------------------------

    def _add(self, text: str, sender: Optional[str]) -> None:
        h = _exact_hash(text)
        vec = _vectorize(text, self.ngram_size)
        entry = SeenEntry(
            text=text,
            text_hash=h,
            vector=vec,
            timestamp=time.time(),
            sender=sender,
        )
        # Ha a puffer tele van és kidobunk egy régi elemet,
        # eltávolítjuk a hash-t is (ha már nincs a pufferben)
        if len(self._buffer) >= self.window_size:
            old = self._buffer[0]
            # Csak akkor töröljük a hash-t, ha nincs más azonos hash a pufferben
            if not any(e.text_hash == old.text_hash for e in list(self._buffer)[1:]):
                self._exact_hashes.pop(old.text_hash, None)

        self._buffer.append(entry)
        self._exact_hashes[h] = entry.timestamp

        if self.cache_path:
            self._save_cache()

    def _load_cache(self) -> None:
        """Gyorsítótár betöltése JSON fájlból."""
        try:
            with open(self.cache_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            for item in data.get("entries", []):
                entry = SeenEntry(
                    text=item["text"],
                    text_hash=item["text_hash"],
                    vector=item["vector"],
                    timestamp=item.get("timestamp", time.time()),
                    sender=item.get("sender"),
                    similarity_hits=item.get("similarity_hits", 0),
                )
                self._buffer.append(entry)
                self._exact_hashes[entry.text_hash] = entry.timestamp
        except (json.JSONDecodeError, KeyError, OSError):
            pass  # hibás gyorsítótár: csendben indulunk üresen

    def _save_cache(self) -> None:
        """Gyorsítótár mentése JSON fájlba."""
        if not self.cache_path:
            return
        try:
            data = {
                "threshold": self.threshold,
                "window_size": self.window_size,
                "entries": [
                    {
                        "text": e.text,
                        "text_hash": e.text_hash,
                        "vector": e.vector,
                        "timestamp": e.timestamp,
                        "sender": e.sender,
                        "similarity_hits": e.similarity_hits,
                    }
                    for e in self._buffer
                ],
            }
            tmp = self.cache_path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False)
            os.replace(tmp, self.cache_path)
        except OSError:
            pass

    # -- Statisztikák -------------------------------------------------------

    def stats(self) -> Dict:
        """Visszaadja a szűrő állapotstatisztikáit."""
        total_hits = sum(e.similarity_hits for e in self._buffer)
        return {
            "buffer_size": len(self._buffer),
            "window_size": self.window_size,
            "threshold": self.threshold,
            "ngram_size": self.ngram_size,
            "exact_hashes": len(self._exact_hashes),
            "total_similarity_hits": total_hits,
        }

    def clear(self) -> None:
        """Ürítja a puffert és a hash táblát."""
        self._buffer.clear()
        self._exact_hashes.clear()
        if self.cache_path and os.path.exists(self.cache_path):
            try:
                os.remove(self.cache_path)
            except OSError:
                pass


# ---------------------------------------------------------------------------
# Integrációs helper: broadcast előtti szűrés
# ---------------------------------------------------------------------------

def filter_broadcast(
    messages: List[Dict],
    dedup: DuplicateFilter,
    text_field: str = "content",
    sender_field: str = "sender",
) -> Tuple[List[Dict], List[Dict]]:
    """
    Kiszűri a duplikátumokat egy üzenetlistából broadcast előtt.

    Visszaad: (accepted, rejected) tuple.
    Minden üzenet dict, amely tartalmazza a text_field-et.
    """
    accepted: List[Dict] = []
    rejected: List[Dict] = []
    for msg in messages:
        text = msg.get(text_field, "")
        sender = msg.get(sender_field)
        result = dedup.admit(text, sender)
        if result.is_duplicate:
            msg["_dedup_reason"] = result.reason
            msg["_dedup_similarity"] = round(result.similarity, 4)
            rejected.append(msg)
        else:
            accepted.append(msg)
    return accepted, rejected


# ---------------------------------------------------------------------------
# Bemutató / teszt főprogram
# ---------------------------------------------------------------------------

def _demo(threshold: float, window: int, ngram: int) -> None:
    """Futtat egy interaktív/nem-interaktív demót."""
    dedup = DuplicateFilter(
        threshold=threshold,
        window_size=window,
        ngram_size=ngram,
    )

    test_messages: List[Tuple[str, Optional[str]]] = [
        # 1 – eredeti
        ("A2A Mesh repó implementáció: duplikátum-szűrő hozzáadása a broadcast pipeline-hoz.", "mano"),
        # 2 – majdnem azonos (kisebb eltérés)
        ("A2A Mesh repó implementáció: duplikátum-szűrő hozzáadása a broadcast pipeline-hoz!", "agent_42"),
        # 3 – teljesen más
        ("Témafűzés: közös szobában al-témák külön ágon, hogy ne akadjon össze 5 párhuzamos vita.", "mano"),
        # 4 – hasonló a 3-hoz, de más szavakkal
        ("Témafűzés javaslat: a közös szobában az al-témák külön ágon futnának, így elkerüljük a párhuzamos viták összeakadását.", "agent_7"),
        # 5 – exact duplikátum
        ("A2A Mesh repó implementáció: duplikátum-szűrő hozzáadása a broadcast pipeline-hoz.", "agent_99"),
        # 6 – rövid üzenet
        ("ok", "agent_1"),
        # 7 – rövid üzenet (más)
        ("ok", "agent_2"),
        # 8 – kontextus-tömörítés ötlet
        ("Kontextus-tömörítés: ha a szoba előzménye > X token, automatikus összefoglaló a régi üzenetekből.", "mano"),
        # 9 – kontextus-tömörítés átfogalmazva
        ("Kontextus tömörítés: amikor a szoba előzménye meghaladja az X token limitet, automatikus összefoglalót készítünk a régi üzenetekből.", "agent_3"),
        # 10 – teljesen új téma
        ("Agent-profilok: rövid, gépi olvasható formátum, amely tartalmazza a képességeket és preferenciákat.", "mano"),
    ]

    print("=" * 78)
    print("A2A Mesh – Duplikátum-szűrő demó")
    print(f"  Küszöb: {threshold}  |  Ablak: {window}  |  N-gram: {ngram}")
    print("=" * 78)

    for i, (text, sender) in enumerate(test_messages, 1):
        result = dedup.admit(text, sender)
        status = "❌ ELUTASÍTVA (duplikátum)" if result.is_duplicate else "✅ ELFOGADVA"
        matched_sender = result.matched_entry.sender if result.matched_entry else "—"
        print(f"\n[{i:2d}] {status}")
        print(f"     Feladó:    {sender}")
        print(f"     Szöveg:    {text[:70]}{'…' if len(text) > 70 else ''}")
        print(f"     Hasonlóság: {result.similarity:.4f}")
        print(f"     Ok:        {result.reason}")
        if result.matched_entry:
            print(f"     Találat:   {result.matched_entry.text[:60]}{'…' if len(result.matched_entry.text) > 60 else ''} (küldte: {matched_sender})")

    print("\n" + "=" * 78)
    print("Statisztika:")
    for k, v in dedup.stats().items():
        print(f"  {k}: {v}")
    print("=" * 78)

    # filter_broadcast demo
    print("\nfilter_broadcast() teszt:")
    batch = [
        {"content": "Témafűzés: közös szobában al-témák külön ágon.", "sender": "agent_a"},
        {"content": "Témafűzés: közös szobában al-témák külön ágon.", "sender": "agent_b"},
        {"content": "Agent-profilok: rövid, gépi olvasható formátum.", "sender": "agent_c"},
    ]
    accepted, rejected = filter_broadcast(batch, dedup)
    print(f"  Elfogadva: {len(accepted)}  |  Elutasítva: {len(rejected)}")
    for r in rejected:
        print(f"    [elutasítva] sim={r['_dedup_similarity']} ok={r['_dedup_reason']}: {r['content'][:50]}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="A2A Mesh duplikátum-szűrő – hasonlóság-alapú deduplikáció"
    )
    parser.add_argument(
        "--threshold", type=float, default=0.82,
        help="Hasonlósági küszöb (0..1, alapértelmezett 0.82)"
    )
    parser.add_argument(
        "--window", type=int, default=150,
        help="Csúszó ablak mérete (alapértelmezett 150)"
    )
    parser.add_argument(
        "--ngram", type=int, default=3,
        help="Karakter n-gram méret (alapértelmezett 3)"
    )
    parser.add_argument(
        "--interactive", action="store_true",
        help="Interaktív mód: üzeneteket olvas stdin-ről"
    )
    args = parser.parse_args()

    if args.interactive:
        dedup = DuplicateFilter(
            threshold=args.threshold,
            window_size=args.window,
            ngram_size=args.ngram,
        )
        print("Interaktív mód. Írj üzeneteket (Ctrl+D/Enter üres sor a kilépéshez):")
        for line in sys.stdin:
            line = line.strip()
            if not line:
                break
            result = dedup.admit(line, sender="cli")
            status = "DUP" if result.is_duplicate else "NEW"
            print(f"  [{status}] sim={result.similarity:.4f} reason={result.reason}")
        print("\nStatisztika:", dedup.stats())
    else:
        _demo(args.threshold, args.window, args.ngram)


if __name__ == "__main__":
    main()